import type { ContentEnvelope } from "./envelope";

/**
 * Truthful provenance.
 *
 * Learner-facing branding stays Learners Area; what the platform records about
 * where material came from stays literal. If a package was generated by an AI,
 * converted from an old HTML file, or licensed from a third party, that is what
 * the record says — never "owner authored" by default.
 */

export const PROVENANCE_LABELS: Record<ContentEnvelope["provenance"]["source"], string> = {
  owner_authored: "Owner authored",
  teacher_authored: "Teacher authored",
  ai_authoring: "AI assisted authoring",
  legacy_conversion: "Converted from legacy material",
  third_party: "Third-party material",
  unknown: "Source not stated",
};

/** One human-readable line for staff surfaces and logs. */
export function describeProvenance(envelope: Pick<ContentEnvelope, "provenance">): string {
  const p = envelope.provenance;
  const parts = [PROVENANCE_LABELS[p.source]];
  if (p.organization) parts.push(p.organization);
  if (p.attribution) parts.push(p.attribution);
  if (p.note) parts.push(p.note);
  if (p.sourceUrl) parts.push(p.sourceUrl);
  if (p.originalFilename) parts.push(`file: ${p.originalFilename}`);
  if (p.rights) parts.push(p.rights);
  return parts.join("; ").slice(0, 12000);
}

/** Server-owned record written next to the imported material (never client text). */
export function provenanceRecord(
  envelope: Pick<ContentEnvelope, "provenance" | "module" | "contentType" | "sourceRef" | "schemaVersion">,
  actorUserId: string,
  now: Date,
) {
  return {
    source: envelope.provenance.source,
    sourceRef: envelope.sourceRef,
    module: envelope.module,
    contentType: envelope.contentType,
    schemaVersion: envelope.schemaVersion,
    originalFilename: envelope.provenance.originalFilename ?? null,
    sourceUrl: envelope.provenance.sourceUrl ?? null,
    organization: envelope.provenance.organization ?? null,
    attribution: envelope.provenance.attribution ?? null,
    rights: envelope.provenance.rights ?? null,
    importedAt: now.toISOString(),
    importedBy: actorUserId,
  };
}
